#include <iostream>
#include <string>

class Report {
public:
    Report& title(std::string t) { name = std::move(t); return *this; }
    Report& rows(int n) { count = n; return *this; }
    std::string build() const { return name + ":" + std::to_string(count); }
private:
    std::string name;
    int count = 0;
};

int main() {
    std::cout << Report().title("marks").rows(3).build() << "\n";
    return 0;
}

